import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 53 · Christmas recipe: overnight Christmas morning cinnamon rolls (Google Trends 3/11: christmas treat recipes, christmas breakfast)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, on Christmas morning in my house, nobody is allowed to open a single present until the cinnamon rolls come out of the oven. That's the rule, since nineteen seventy. The children sit on the stairs in their pajamas, smelling cinnamon and butter coming from the kitchen, and it's the longest twenty-five minutes of their whole year.""",
   "cinnamon rolls icing Christmas morning", "THE LONGEST 25 MINUTES")
sc("""But people tell me their cinnamon rolls come out hard and dry, or they never rise, or all the filling leaks out and burns on the pan. So tonight I'm giving you my overnight Christmas cinnamon rolls, every step, and the five mistakes that make them hard. And stay with me, because the last secret is the trick that lets you sleep in on Christmas morning and still have hot rolls.""",
   "hard dry cinnamon rolls pan", "HARD AND DRY")

ch("Grandma Pearl's rolls")
sc("""Grandma Pearl made cinnamon rolls every Saturday on the farm, in her big black wood stove, from a bread dough she'd started before dawn. She never measured anything. A handful of this, a pinch of that, and flour until it felt right. When I asked her for the recipe, she said, Ruthie, I can't tell you. My hands know it, and my hands can't talk.""",
   "1940s farm kitchen bread dough", "MY HANDS CAN'T TALK")
sc("""So the summer I was twelve, I stood next to her every Saturday with a pencil and a notebook, and every time she grabbed a handful, I made her put it in a measuring cup first. She grumbled the whole summer. But by September, I had it all written down. That notebook is in my kitchen drawer, with flour stains on every page.""",
   "old recipe notebook flour stains", "FLOUR ON EVERY PAGE")
sc("""And here's the good news. Cinnamon rolls aren't hard, honey. They just take patience. Most of the time is the dough sitting and rising, and you're doing something else. In a minute I'll tell you the first mistake, and it happens in the first thirty seconds, before you even start mixing.""",
   "dough rising bowl towel", "THEY JUST TAKE PATIENCE")

ch("What you need")
sc("""Here's what you need for twelve big rolls. For the dough, one cup of warm milk. One packet of yeast, that's two and a quarter teaspoons. A quarter cup of sugar. One egg. A third of a cup of melted butter. One teaspoon of salt. And about three and a half cups of flour. For the filling, a stick of soft butter, one cup of packed brown sugar, and two tablespoons of cinnamon.""",
   "flour yeast milk butter cinnamon", "THE INGREDIENTS")
sc("""And for the icing, four ounces of cream cheese, softened. A quarter cup of soft butter. One and a half cups of powdered sugar. A teaspoon of vanilla. And a splash of milk. Grandma Pearl used a simple powdered sugar glaze, but I started using cream cheese in nineteen eighty-two, and nobody in my family has let me go back.""",
   "cream cheese icing bowl", "NOBODY LETS ME GO BACK")

ch("The dough")
sc("""Step one, and here's mistake number one. Milk that's too hot. Hot milk kills the yeast, and your rolls never rise. Warm the milk until it's just warm, like a baby's bottle, about one hundred ten degrees. Put a drop on your wrist. It should feel warm, not hot. Stir in the yeast and a spoon of the sugar, and wait five minutes. It should get foamy on top.""",
   "foamy yeast warm milk", "LIKE A BABY'S BOTTLE")
sc("""If it doesn't foam, honey, your yeast is old or your milk was too hot. Throw it out and start again. It's a quarter of a cup of milk. Better to lose that than three hours and a whole batch of dough. Then add the rest of the sugar, the egg, the melted butter, and the salt, and stir.""",
   "checking yeast foam bowl", "START AGAIN")
sc("""Now add the flour a cup at a time, mixing with a wooden spoon, until a soft dough forms. Turn it out on a floured counter and knead it for about five minutes, pushing it away with the heel of your hand, folding it back, and turning it. Mistake number two is adding too much flour. The dough should be soft and a little tacky, like the back of a sticky note. Too much flour makes hard rolls.""",
   "kneading soft dough counter", "SOFT AND A LITTLE TACKY")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Put the dough in a buttered bowl, cover it with a towel, and set it somewhere warm, like on top of the refrigerator or in the oven with just the light on. Let it rise until it's doubled, about an hour to an hour and a half.""",
   "dough doubled in bowl", "DOUBLED IN SIZE")

sc("""And if your kitchen is cold, honey, like mine every December, here's how to help the dough rise. Turn the oven on to its lowest setting for just one minute, then turn it off. Put the bowl of dough inside with the door closed. It's warm and cozy in there, like a little bread hotel. Just don't forget it's there and turn the oven on to preheat. I did that once in nineteen ninety-one. The bowl melted.""",
   "dough bowl inside warm oven", "A LITTLE BREAD HOTEL")

ch("Rolling and filling")
sc("""Step two. Punch the dough down gently, and roll it out on a floured counter into a big rectangle, about sixteen by twelve inches. Spread the soft butter all over it, right to the edges, except leave one long edge bare, about an inch. Then mix the brown sugar and cinnamon, and sprinkle it evenly over the butter. Press it in lightly with your hand.""",
   "spreading butter cinnamon sugar dough", "RIGHT TO THE EDGES")
sc("""Mistake number three is melted butter in the filling. Melted butter runs out the sides while it bakes, and takes the sugar with it, and it all burns on the bottom of the pan. Use soft butter, like for toast. It holds the cinnamon sugar in place, and it melts slowly inside the rolls, into that gooey swirl everybody fights over.""",
   "soft butter spread dough", "SOFT, NOT MELTED")
sc("""Now roll it up, starting from the long side with the filling, toward the bare edge, nice and snug. Pinch the bare edge to seal it. Then cut it into twelve rolls. And here's my favorite trick. Don't use a knife. Use a piece of plain dental floss. Slide it under the log, cross the ends over the top, and pull. It cuts a perfect round roll without squashing it.""",
   "cutting cinnamon roll log dental floss", "DENTAL FLOSS")
sc("""Put the rolls in a buttered nine by thirteen pan, cut side up, three rows of four, with a little space between them. They'll grow together as they rise and bake. And here's the next part. So far, warm milk not hot, a soft dough, soft butter in the filling, rolled snug and cut with floss. Now the secret I promised, for Christmas morning.""",
   "cinnamon rolls in baking pan", "THREE ROWS OF FOUR")

ch("The overnight secret")
sc("""Instead of letting them rise and baking them right away, cover the pan tightly with plastic wrap, and put it in the icebox on Christmas Eve. The cold slows the yeast way down, and the rolls rise very slowly all night. You can leave them in the icebox for up to sixteen hours. That's the secret. All the work is done the night before.""",
   "pan covered plastic wrap refrigerator", "THE NIGHT BEFORE")
sc("""On Christmas morning, take the pan out and set it on the counter for about forty-five minutes to an hour, until the rolls are puffy and almost doubled. Mistake number four is baking them straight from the icebox, cold. They come out dense and heavy in the middle. Give them time to wake up, honey. Put on the coffee and the carols while they rise.""",
   "puffy risen cinnamon rolls morning", "LET THEM WAKE UP")

ch("Baking")
sc("""Bake them at three hundred fifty degrees for twenty-two to twenty-six minutes, until they're golden brown on top. And mistake number five. Overbaking them. That's the main reason cinnamon rolls come out hard. The centers should be just done, at about one hundred ninety degrees if you use a thermometer. If the tops brown too fast, lay a piece of foil over the pan for the last ten minutes.""",
   "golden cinnamon rolls oven", "DON'T OVERBAKE")
sc("""While they bake, make the icing. Beat the soft cream cheese and butter together until smooth. Add the powdered sugar and vanilla, and beat until fluffy. Add a little milk if it's too thick. Then when the rolls come out, let them cool for five minutes, and spread the icing over them while they're warm, so it melts into all the swirls.""",
   "spreading icing warm cinnamon rolls", "WHILE THEY'RE WARM")
sc("""And then I ring the little brass bell from Grandma Pearl's farm, and the children come running down the stairs. One roll each, a glass of milk, and then, and only then, the presents. My grandson is thirty-four now, honey, with children of his own. And he still sits on the stairs and waits for that bell.""",
   "children running down stairs Christmas", "THE LITTLE BRASS BELL")

ch("Keeping")
sc("""Cinnamon rolls are best the day they're made, but they keep two days covered on the counter. Warm one in the microwave for fifteen seconds, and it's soft again. And they freeze beautifully, unfrosted. Wrap them tight and freeze them for two months. Thaw them overnight, warm them in the oven, and frost them. A pan of frozen rolls is the best present for a new mother.""",
   "frozen cinnamon rolls wrapped", "FOR A NEW MOTHER")

ch("Grandma's kitchen")
sc("""So one more time. Warm milk, not hot, and wait for the foam. A soft, tacky dough, don't add too much flour. Soft butter in the filling, not melted. Roll it snug and cut it with floss. Into the icebox on Christmas Eve. Let them wake up an hour in the morning. Bake them just until golden, and frost them warm. That's Grandma Pearl's cinnamon rolls, written down at last.""",
   "pan of cinnamon rolls Christmas table", "WRITTEN DOWN AT LAST")
sc("""Tell me in the comments, sweetheart. What does your family eat on Christmas morning? Cinnamon rolls, a casserole, pancakes? I'd love to know. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas morning breakfast family", "WHAT'S YOUR CHRISTMAS BREAKFAST?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma53", "Christmas Morning Cinnamon Rolls That NEVER Turn Out HARD",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Yeast activity: liquid around 105 to 110 F; refrigerated overnight rise for enriched doughs.",
      "Recipe as written by Grandma Ruth: dough of 1 cup warm milk, 2 1/4 tsp yeast, 1/4 cup sugar, 1 egg, 1/3 cup melted butter, 1 tsp salt, about 3 1/2 cups flour; filling of 1/2 cup soft butter, 1 cup brown sugar, 2 tbsp cinnamon; 350 F for 22 to 26 minutes; cream cheese icing."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
